/**
 * Private lifecycle bootstrap for MCP -> Core Delegate forwarding.
 *
 * Forwarding key material is generated by the Core supervisor and exists only
 * in process memory. Core workers receive verifier material over their existing
 * parent/child IPC channel. Reloadable MCP backends subscribe over a private
 * local IPC socket authenticated with the supervisor control lease.
 */
import crypto from "node:crypto";
import fs from "node:fs";
import net from "node:net";
import path from "node:path";
import type { ChildProcess } from "node:child_process";
import { getRootConfigDir } from "../config/paths.js";
import {
  installDelegateForwardedVerifier,
  provisionDelegateForwardedSigner,
  type DelegateForwardedChannelMaterial,
} from "../browserTransport/delegateForwardedPrincipal.js";

const MAX_IPC_LINE = 4096;
const DEFAULT_CORE_PORT = 7888;

type MaterialWire = Readonly<{ channelId: string; key: string }>;
type SupervisorDiscovery = Readonly<{
  supervisorPid: number;
  publicPort: number;
  controlPort: number;
  controlToken: string;
}>;

type CoreWorkerReady = Readonly<{
  type: "core-delegate-forward-ready";
  pid: number;
  generationId: string;
}>;

type CoreWorkerInstall = Readonly<{
  type: "core-delegate-forward-install";
  generationId: string;
  material: MaterialWire;
}>;

type CoreWorkerInstalled = Readonly<{
  type: "core-delegate-forward-installed";
  pid: number;
  generationId: string;
  channelId: string;
}>;

function safeTokenEqual(a: unknown, b: string): boolean {
  if (typeof a !== "string") return false;
  const left = Buffer.from(a, "utf8");
  const right = Buffer.from(b, "utf8");
  return left.length === right.length && crypto.timingSafeEqual(left, right);
}

function validChannelId(value: unknown): value is string {
  return typeof value === "string" && /^[A-Za-z0-9_-]{22,64}$/.test(value);
}

function materialToWire(material: DelegateForwardedChannelMaterial): MaterialWire {
  return {
    channelId: material.channelId,
    key: Buffer.from(material.key).toString("base64url"),
  };
}

export function delegateForwardingMaterialFromWire(value: unknown): DelegateForwardedChannelMaterial {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("DELEGATE_FORWARD_BRIDGE_MATERIAL_INVALID");
  }
  const wire = value as Partial<MaterialWire>;
  if (!validChannelId(wire.channelId) || typeof wire.key !== "string" ||
      !/^[A-Za-z0-9_-]{43}$/.test(wire.key)) {
    throw new Error("DELEGATE_FORWARD_BRIDGE_MATERIAL_INVALID");
  }
  const key = Buffer.from(wire.key, "base64url");
  if (key.byteLength !== 32 || key.every(byte => byte === 0)) {
    throw new Error("DELEGATE_FORWARD_BRIDGE_MATERIAL_INVALID");
  }
  return { channelId: wire.channelId, key };
}

export function delegateForwardingPipePath(publicPort: number, supervisorPid: number): string {
  if (!Number.isSafeInteger(publicPort) || publicPort < 1 || publicPort > 65535 ||
      !Number.isSafeInteger(supervisorPid) || supervisorPid < 1) {
    throw new Error("DELEGATE_FORWARD_BRIDGE_IDENTITY_INVALID");
  }
  if (process.platform === "win32") {
    return `\\\\.\\pipe\\superagent-delegate-forward-${publicPort}-${supervisorPid}`;
  }
  return path.join(getRootConfigDir(), `delegate-forward-${publicPort}-${supervisorPid}.sock`);
}

function readSupervisorDiscovery(port: number): SupervisorDiscovery {
  const file = path.join(getRootConfigDir(), `core-supervisor-${port}.json`);
  const value = JSON.parse(fs.readFileSync(file, "utf8")) as Partial<SupervisorDiscovery>;
  if (value.publicPort !== port || !Number.isSafeInteger(value.supervisorPid) ||
      Number(value.supervisorPid) < 1 || !Number.isSafeInteger(value.controlPort) ||
      Number(value.controlPort) < 1 || Number(value.controlPort) > 65535 ||
      typeof value.controlToken !== "string" || !/^[a-f0-9]{64}$/.test(value.controlToken)) {
    throw new Error("DELEGATE_FORWARD_BRIDGE_DISCOVERY_INVALID");
  }
  return value as SupervisorDiscovery;
}

function parseOneLine(socket: net.Socket, timeoutMs: number): Promise<unknown> {
  return new Promise((resolve, reject) => {
    let data = "";
    let settled = false;
    const finish = (error?: Error, value?: unknown) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      socket.off("data", onData);
      socket.off("error", onError);
      if (error) reject(error); else resolve(value);
    };
    const onError = () => finish(new Error("DELEGATE_FORWARD_BRIDGE_IPC_FAILED"));
    const onData = (chunk: Buffer | string) => {
      data += chunk.toString();
      if (Buffer.byteLength(data, "utf8") > MAX_IPC_LINE) {
        finish(new Error("DELEGATE_FORWARD_BRIDGE_IPC_INVALID"));
        return;
      }
      const newline = data.indexOf("\n");
      if (newline < 0) return;
      try { finish(undefined, JSON.parse(data.slice(0, newline))); }
      catch { finish(new Error("DELEGATE_FORWARD_BRIDGE_IPC_INVALID")); }
    };
    const timer = setTimeout(
      () => finish(new Error("DELEGATE_FORWARD_BRIDGE_IPC_TIMEOUT")),
      timeoutMs,
    );
    socket.on("data", onData);
    socket.once("error", onError);
  });
}

export async function requestDelegateForwardingMaterial(
  discovery: SupervisorDiscovery,
  timeoutMs = 1200,
): Promise<{ material: DelegateForwardedChannelMaterial; socket: net.Socket }> {
  const pipe = delegateForwardingPipePath(discovery.publicPort, discovery.supervisorPid);
  const socket = net.createConnection(pipe);
  await new Promise<void>((resolve, reject) => {
    const timer = setTimeout(() => {
      socket.destroy();
      reject(new Error("DELEGATE_FORWARD_BRIDGE_IPC_TIMEOUT"));
    }, timeoutMs);
    socket.once("connect", () => {
      clearTimeout(timer);
      resolve();
    });
    socket.once("error", () => {
      clearTimeout(timer);
      reject(new Error("DELEGATE_FORWARD_BRIDGE_IPC_FAILED"));
    });
  });
  socket.write(JSON.stringify({
    type: "delegate-forward-subscribe",
    role: "mcp-signer",
    pid: process.pid,
    token: discovery.controlToken,
  }) + "\n");
  const response = await parseOneLine(socket, timeoutMs) as any;
  if (response?.type !== "delegate-forward-material" ||
      response?.supervisorPid !== discovery.supervisorPid ||
      response?.publicPort !== discovery.publicPort) {
    socket.destroy();
    throw new Error("DELEGATE_FORWARD_BRIDGE_IPC_DENIED");
  }
  const material = delegateForwardingMaterialFromWire(response.material);
  return { material, socket };
}

export async function startCoreSupervisorDelegateForwardingBroker(options: {
  publicPort: number;
  supervisorPid?: number;
  controlToken: string;
  material: DelegateForwardedChannelMaterial;
}): Promise<{ path: string; close: () => Promise<void> }> {
  const supervisorPid = options.supervisorPid ?? process.pid;
  if (!/^[a-f0-9]{64}$/.test(options.controlToken)) {
    throw new Error("DELEGATE_FORWARD_BRIDGE_CONTROL_INVALID");
  }
  const pipe = delegateForwardingPipePath(options.publicPort, supervisorPid);
  if (process.platform !== "win32") {
    try { fs.rmSync(pipe, { force: true }); } catch {}
    fs.mkdirSync(path.dirname(pipe), { recursive: true });
  }
  const server = net.createServer(socket => {
    socket.setNoDelay(true);
    let data = "";
    let authenticated = false;
    const deny = () => {
      try { socket.end(JSON.stringify({ type: "delegate-forward-denied" }) + "\n"); }
      catch { socket.destroy(); }
    };
    socket.on("data", chunk => {
      if (authenticated) return;
      data += chunk.toString();
      if (Buffer.byteLength(data, "utf8") > MAX_IPC_LINE) {
        deny();
        return;
      }
      const newline = data.indexOf("\n");
      if (newline < 0) return;
      let request: any;
      try { request = JSON.parse(data.slice(0, newline)); }
      catch { deny(); return; }
      if (request?.type !== "delegate-forward-subscribe" ||
          request?.role !== "mcp-signer" ||
          !Number.isSafeInteger(request?.pid) || request.pid < 1 ||
          !safeTokenEqual(request?.token, options.controlToken)) {
        deny();
        return;
      }
      authenticated = true;
      socket.write(JSON.stringify({
        type: "delegate-forward-material",
        supervisorPid,
        publicPort: options.publicPort,
        material: materialToWire(options.material),
      }) + "\n");
    });
  });
  await new Promise<void>((resolve, reject) => {
    server.once("error", reject);
    server.listen(pipe, () => resolve());
  });
  if (process.platform !== "win32") {
    try { fs.chmodSync(pipe, 0o600); } catch {}
  }
  return {
    path: pipe,
    close: () => new Promise<void>(resolve => {
      server.close(() => {
        if (process.platform !== "win32") {
          try { fs.rmSync(pipe, { force: true }); } catch {}
        }
        resolve();
      });
    }),
  };
}

export function startMcpDelegateForwardingSubscription(
  publicPort = DEFAULT_CORE_PORT,
  options: { retryMs?: number; initialDeadlineMs?: number } = {},
): { firstReady: Promise<boolean>; close: () => void } {
  const retryMs = Math.max(250, Math.min(options.retryMs ?? 1000, 10_000));
  const initialDeadlineMs = Math.max(200, Math.min(options.initialDeadlineMs ?? 1200, 10_000));
  let stopped = false;
  let currentSocket: net.Socket | undefined;
  let retryTimer: ReturnType<typeof setTimeout> | undefined;
  let firstSettled = false;
  let firstResolve!: (ready: boolean) => void;
  const firstReady = new Promise<boolean>(resolve => { firstResolve = resolve; });
  const settleFirst = (ready: boolean) => {
    if (firstSettled) return;
    firstSettled = true;
    firstResolve(ready);
  };
  const schedule = () => {
    if (stopped || retryTimer) return;
    retryTimer = setTimeout(() => {
      retryTimer = undefined;
      void connect();
    }, retryMs);
    retryTimer.unref?.();
  };
  const connect = async () => {
    if (stopped) return;
    try {
      const discovery = readSupervisorDiscovery(publicPort);
      const result = await requestDelegateForwardingMaterial(discovery, initialDeadlineMs);
      if (stopped) { result.socket.destroy(); return; }
      provisionDelegateForwardedSigner(result.material);
      currentSocket?.destroy();
      currentSocket = result.socket;
      settleFirst(true);
      const reconnect = () => {
        if (currentSocket === result.socket) currentSocket = undefined;
        schedule();
      };
      result.socket.once("close", reconnect);
      result.socket.once("error", reconnect);
    } catch {
      settleFirst(false);
      schedule();
    }
  };
  void connect();
  return {
    firstReady,
    close() {
      stopped = true;
      if (retryTimer) clearTimeout(retryTimer);
      retryTimer = undefined;
      currentSocket?.destroy();
      currentSocket = undefined;
      settleFirst(false);
    },
  };
}

export async function bootstrapCoreWorkerDelegateForwardingVerifier(
  timeoutMs = 10_000,
): Promise<void> {
  if (process.env.SUPERAGENT_CORE_WORKER !== "1") return;
  if (!process.send) throw new Error("DELEGATE_FORWARD_CORE_IPC_REQUIRED");
  const generationId = process.env.SUPERAGENT_CORE_GENERATION_ID || "";
  if (!/^[a-f0-9]{32}$/.test(generationId)) {
    throw new Error("DELEGATE_FORWARD_CORE_GENERATION_INVALID");
  }
  await new Promise<void>((resolve, reject) => {
    let settled = false;
    const finish = (error?: Error) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      process.off("message", onMessage);
      if (error) reject(error); else resolve();
    };
    const onMessage = (value: unknown) => {
      const message = value as Partial<CoreWorkerInstall> | null;
      if (message?.type !== "core-delegate-forward-install" ||
          message.generationId !== generationId) return;
      try {
        const material = delegateForwardingMaterialFromWire(message.material);
        installDelegateForwardedVerifier(material);
        process.send?.({
          type: "core-delegate-forward-installed",
          pid: process.pid,
          generationId,
          channelId: material.channelId,
        } satisfies CoreWorkerInstalled);
        finish();
      } catch {
        finish(new Error("DELEGATE_FORWARD_CORE_INSTALL_FAILED"));
      }
    };
    const timer = setTimeout(
      () => finish(new Error("DELEGATE_FORWARD_CORE_BOOTSTRAP_TIMEOUT")),
      timeoutMs,
    );
    process.on("message", onMessage);
    process.send?.({
      type: "core-delegate-forward-ready",
      pid: process.pid,
      generationId,
    } satisfies CoreWorkerReady);
  });
}

export async function provisionCoreWorkerDelegateForwardingVerifier(
  child: ChildProcess,
  generationId: string,
  material: DelegateForwardedChannelMaterial,
  timeoutMs = 10_000,
): Promise<void> {
  if (!child.pid || !child.send) throw new Error("DELEGATE_FORWARD_CORE_IPC_REQUIRED");
  await new Promise<void>((resolve, reject) => {
    let installed = false;
    const finish = (error?: Error) => {
      clearTimeout(timer);
      child.off("message", onMessage);
      child.off("exit", onExit);
      child.off("error", onError);
      if (error) reject(error); else resolve();
    };
    const onExit = () => finish(new Error("DELEGATE_FORWARD_CORE_EXITED"));
    const onError = () => finish(new Error("DELEGATE_FORWARD_CORE_IPC_FAILED"));
    const onMessage = (value: unknown) => {
      const ready = value as Partial<CoreWorkerReady> | null;
      if (ready?.type === "core-delegate-forward-ready" &&
          ready.pid === child.pid && ready.generationId === generationId) {
        try {
          child.send?.({
            type: "core-delegate-forward-install",
            generationId,
            material: materialToWire(material),
          } satisfies CoreWorkerInstall, error => {
            if (error) finish(new Error("DELEGATE_FORWARD_CORE_IPC_FAILED"));
          });
        } catch { finish(new Error("DELEGATE_FORWARD_CORE_IPC_FAILED")); }
        return;
      }
      const ack = value as Partial<CoreWorkerInstalled> | null;
      if (!installed && ack?.type === "core-delegate-forward-installed" &&
          ack.pid === child.pid && ack.generationId === generationId &&
          ack.channelId === material.channelId) {
        installed = true;
        finish();
      }
    };
    const timer = setTimeout(
      () => finish(new Error("DELEGATE_FORWARD_CORE_BOOTSTRAP_TIMEOUT")),
      timeoutMs,
    );
    child.on("message", onMessage);
    child.once("exit", onExit);
    child.once("error", onError);
  });
}
